programa
{
    funcao inicio()
    {
        real salario
        leia(salario)
        se (salario <= 0)
        {
            escreva("Valor inválido")
        }
        senao se (salario < 2500)
        {
            salario = salario * 1.10
            escreva("Novo salário: ", salario)
        }
        senao
        {
            escreva("Sem reajuste")
        }
    }
}

